package kr.minecraft.survival.civic;

import java.lang.reflect.Proxy;
import java.nio.file.*;
import java.util.*;
import net.milkbowl.vault.economy.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.ServicePriority;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.mockbukkit.mockbukkit.*;
import org.mockbukkit.mockbukkit.entity.PlayerMock;
import kr.minecraft.survival.economy.KoreanEconomyPlugin;
import kr.minecraft.survival.economy.domain.*;
import static kr.minecraft.survival.economy.domain.ActionEngine.*;

class CivicTest {
    ServerMock server;KoreanEconomyPlugin core;KoreanCivicPlugin plugin;SavedPlayer seller,buyer;StateStore db;CivicStore store;Path root;Map<UUID,Double> money=new HashMap<>();boolean refuse,uncertain;Runnable walletHook;
    static class SavedPlayer extends PlayerMock{int saves,failOn=-1;SavedPlayer(ServerMock s,String n){super(s,n);}@Override public void saveData(){if(++saves==failOn)throw new IllegalStateException("save fault");}}
    @BeforeEach void start(){server=MockBukkit.mock();server.addSimpleWorld("world");root=Path.of(System.getProperty("civic.repo"));var vault=MockBukkit.createMockPlugin("Vault");Economy wallet=(Economy)Proxy.newProxyInstance(Economy.class.getClassLoader(),new Class[]{Economy.class},(o,m,a)->{String n=m.getName();UUID id=a!=null&&a.length>0&&a[0] instanceof OfflinePlayer p?p.getUniqueId():null;if(n.equals("has"))return money.getOrDefault(id,0.0)>=(double)a[a.length-1];if(n.equals("getBalance"))return money.getOrDefault(id,0.0);if(n.equals("depositPlayer")||n.equals("withdrawPlayer")){if(walletHook!=null)walletHook.run();if(uncertain)throw new IllegalStateException("uncertain wallet");double v=(double)a[a.length-1],old=money.getOrDefault(id,0.0);if(refuse||(n.equals("withdrawPlayer")&&old<v))return new EconomyResponse(0,old,EconomyResponse.ResponseType.FAILURE,"refused");double next=old+(n.equals("depositPlayer")?v:-v);money.put(id,next);return new EconomyResponse(v,next,EconomyResponse.ResponseType.SUCCESS,"");}if(m.getReturnType()==boolean.class)return true;if(m.getReturnType()==int.class)return 2;if(m.getReturnType()==double.class)return 0.0;if(n.equals("toString"))return "CivicTestWallet";return null;});server.getServicesManager().register(Economy.class,wallet,vault,ServicePriority.Normal);
        core=MockBukkit.loadWith(KoreanEconomyPlugin.class,root.resolve("개발자료/플러그인/생활경제/src/main/resources/plugin.yml").toFile());assertTrue(core.isEnabled());server.getPluginManager().addPermissions(core.getDescription().getPermissions());plugin=MockBukkit.loadWith(KoreanCivicPlugin.class,root.resolve("개발자료/플러그인/마을상점/src/main/resources/plugin.yml").toFile());assertTrue(plugin.isEnabled());server.getPluginManager().addPermissions(plugin.getDescription().getPermissions());db=core.getEconomyStateStore();store=plugin.store;seller=player("Seller");buyer=player("Buyer");}
    SavedPlayer player(String name){var p=new SavedPlayer(server,name);server.addPlayer(p);p.setGameMode(GameMode.SURVIVAL);p.teleport(new Location(server.getWorld("world"),.5,65,.5));money.put(p.getUniqueId(),100000.0);core.prepareFarmingPlayer(p);return p;}
    @AfterEach void stop(){MockBukkit.unmock();}
    void click(PlayerMock who,int slot){var e=new InventoryClickEvent(who.getOpenInventory(),InventoryType.SlotType.CONTAINER,slot,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());server.getScheduler().performTicks(2);}
    CivicStore.Plot town(){plugin.found(seller,"도시마을",seller.getWorld().getUID().toString(),0,0);return store.plots().getFirst();}
    boolean allowed(Player p){return core.canFarmAt(p,p.getLocation());}
    ItemStack item(){ItemStack item=new ItemStack(Material.DIAMOND,5);var meta=item.getItemMeta();meta.setDisplayName("§b특별한 다이아몬드");meta.getPersistentDataContainer().set(new NamespacedKey("koreanfarming","item"),PersistentDataType.STRING,"strawberry_seed");meta.setItemModel(new NamespacedKey("tycoon","farm/strawberry_seed"));item.setItemMeta(meta);return item;}
    CivicStore.Listing listing(){var item=item();seller.getInventory().setItemInMainHand(item);plugin.list(seller,item,3,5000);return store.listings(null).getFirst();}
    @Test void nativeSerializationRetainsExactCustomDataAndQuantity(){var item=item();assertEquals(item,ItemStack.deserializeBytes(item.serializeAsBytes()));}
    @Test void townChargesAndNativeGuardsPreservePrivateQuota(){var plot=town();assertEquals(90000,money.get(seller.getUniqueId()));assertEquals("ACTIVE",db.land(plot.world(),0,0).state());assertTrue(allowed(seller));assertFalse(allowed(buyer));assertEquals(0,db.lands(seller.getUniqueId()).size());assertEquals(0,db.landCost(seller.getUniqueId(),250000));assertThrows(StateStore.Denied.class,()->db.abandon(seller.getUniqueId(),plot.world(),0,0));}
    @Test void expansionRequiresAdjacentSameWorldAndFounder(){var first=town();seller.teleport(new Location(seller.getWorld(),16.5,65,.5));plugin.expand(seller,first.town(),first.world(),1,0);assertEquals(87500,money.get(seller.getUniqueId()));assertEquals(2,store.plots().size());seller.teleport(new Location(seller.getWorld(),64.5,65,.5));assertThrows(StateStore.Denied.class,()->plugin.expand(seller,first.town(),first.world(),4,0));buyer.teleport(new Location(buyer.getWorld(),32.5,65,.5));assertThrows(StateStore.Denied.class,()->plugin.expand(buyer,first.town(),first.world(),2,0));}
    @Test void namesLimitsExistingClaimsAndWorldBoundaryNeverCharge(){var first=town();assertThrows(StateStore.Denied.class,()->store.reserveTown(seller.getUniqueId(),first.world(),2,2,"다른마을",0,64));buyer.teleport(new Location(buyer.getWorld(),32.5,65,.5));assertThrows(StateStore.Denied.class,()->plugin.found(buyer,"도시마을",first.world(),2,0));assertThrows(StateStore.Denied.class,()->plugin.found(buyer,"새마을",first.world(),0,0));assertEquals(100000,money.get(buyer.getUniqueId()));assertEquals(1,store.plots().size());}
    @Test void plotSaleTransfersProtectionAndCreditsOnlyOnce(){var plot=town();plugin.sellPlot(seller,plot.id(),50000);plugin.buyPlot(buyer,plot.id(),50000);assertEquals(buyer.getUniqueId().toString(),store.plot(plot.id()).owner());assertEquals(99500,money.get(buyer.getUniqueId()));assertEquals(90000,money.get(seller.getUniqueId()));assertEquals(50000,store.credit(seller.getUniqueId()));assertFalse(allowed(seller));assertTrue(allowed(buyer));assertThrows(StateStore.Denied.class,()->plugin.buyPlot(buyer,plot.id(),50000));plugin.collect(seller);assertEquals(90500,money.get(seller.getUniqueId()));assertEquals(0,store.credit(seller.getUniqueId()));assertThrows(StateStore.Denied.class,()->plugin.collect(seller));plugin.sellPlot(buyer,plot.id(),70000);plugin.buyPlot(seller,plot.id(),70000);assertEquals(seller.getUniqueId().toString(),store.plot(plot.id()).owner());assertEquals(70000,store.credit(buyer.getUniqueId()));}
    @Test void refusedPlotPurchaseRestoresOriginalTitleAndPrice(){var plot=town();plugin.sellPlot(seller,plot.id(),50000);refuse=true;plugin.buyPlot(buyer,plot.id(),50000);assertEquals("ACTIVE",store.plot(plot.id()).state());assertEquals("ACTIVE",db.land(plot.world(),0,0).state());assertEquals(seller.getUniqueId().toString(),db.land(plot.world(),0,0).owner());assertEquals(50000,store.plot(plot.id()).price());assertTrue(allowed(seller));assertEquals(0,store.credit(seller.getUniqueId()));refuse=false;plugin.buyPlot(buyer,plot.id(),50000);assertTrue(allowed(buyer));}
    @Test void plotStalePriceAndSelfPurchaseDoNotDebit(){var plot=town();plugin.sellPlot(seller,plot.id(),50000);assertThrows(StateStore.Denied.class,()->plugin.buyPlot(seller,plot.id(),50000));plugin.sellPlot(seller,plot.id(),60000);assertThrows(StateStore.Denied.class,()->plugin.buyPlot(buyer,plot.id(),50000));assertEquals(100000,money.get(buyer.getUniqueId()));assertTrue(allowed(seller));}
    @Test void uncertainPlotLocksOwnerAndBuyerUntilManualReconciliation(){var plot=town();plugin.sellPlot(seller,plot.id(),50000);uncertain=true;plugin.buyPlot(buyer,plot.id(),50000);assertEquals("LOCKED",store.plot(plot.id()).state());assertFalse(allowed(seller));assertFalse(allowed(buyer));String id=store.plot(plot.id()).receipt();assertThrows(StateStore.Denied.class,()->db.resolve(id,false,"operator"));assertThrows(StateStore.Denied.class,()->plugin.buyPlot(buyer,plot.id(),50000));uncertain=false;plugin.admin(server.getConsoleSender(),new String[]{"취소",id,"확인"});assertTrue(allowed(seller));assertEquals("ACTIVE",store.plot(plot.id()).state());assertEquals(100000,money.get(buyer.getUniqueId()));}
    @Test void insufficientTownFundsReleasesReservationAndLease(){money.put(seller.getUniqueId(),0.0);plugin.found(seller,"도시마을",seller.getWorld().getUID().toString(),0,0);assertTrue(store.plots().isEmpty());assertNull(store.founded(seller.getUniqueId()));assertTrue(allowed(buyer));money.put(seller.getUniqueId(),20000.0);town();assertEquals(1,store.plots().size());}
    @Test void leasedUnclaimedAreaIsProtectedAndBlocksPrivateClaims(){String w=seller.getWorld().getUID().toString();UUID lease=UUID.randomUUID();core.holdLand(lease,w,0,0);assertFalse(allowed(seller));assertFalse(allowed(buyer));assertThrows(StateStore.Denied.class,()->core.assertChunkAvailable(seller,seller.getWorld(),0,0));buyer.performCommand("땅보호 생성 확인");assertNull(db.land(w,0,0));core.releaseLand(lease);assertTrue(allowed(buyer));}
    @Test void activeFarmRecordsPreventListingAndBuyingPlot(){var plot=town();db.execute("CREATE TABLE farm_plots(world TEXT,x INTEGER,y INTEGER,z INTEGER)");db.execute("INSERT INTO farm_plots VALUES(?,0,65,0)",plot.world());assertThrows(StateStore.Denied.class,()->plugin.sellPlot(seller,plot.id(),50000));db.execute("DELETE FROM farm_plots");plugin.sellPlot(seller,plot.id(),50000);db.execute("INSERT INTO farm_plots VALUES(?,15,65,15)",plot.world());assertThrows(StateStore.Denied.class,()->plugin.buyPlot(buyer,plot.id(),50000));assertTrue(allowed(seller));}
    @Test void escrowRemovesOnlyChosenQuantityAndRestoresExactItemOnPurchase(){var row=listing();assertEquals(2,seller.getInventory().getItemInMainHand().getAmount());assertEquals(0,store.credit(seller.getUniqueId()));plugin.buyItem(buyer,row.id(),5000,false);ItemStack expected=item();expected.setAmount(3);assertEquals(expected,buyer.getInventory().getItem(0));assertEquals(99950,money.get(buyer.getUniqueId()));assertEquals(5000,store.credit(seller.getUniqueId()));assertTrue(store.listings(null).isEmpty());assertThrows(StateStore.Denied.class,()->plugin.buyItem(buyer,row.id(),5000,false));}
    @Test void fullBagNeverDebitsOrConsumesListing(){var row=listing();for(int i=0;i<36;i++)buyer.getInventory().setItem(i,new ItemStack(Material.COBBLESTONE,64));assertThrows(StateStore.Denied.class,()->plugin.buyItem(buyer,row.id(),5000,false));assertEquals("ACTIVE",store.listing(row.id()).state());assertEquals(100000,money.get(buyer.getUniqueId()));}
    @Test void cancellationReturnsOriginalMetadataWithoutMoney(){var row=listing();plugin.buyItem(seller,row.id(),5000,true);assertEquals(item(),seller.getInventory().getItemInMainHand());assertEquals("RETURNED",store.listing(row.id()).state());assertEquals(100000,money.get(seller.getUniqueId()));assertEquals(0,store.credit(seller.getUniqueId()));}
    @Test void staleHandAndGuiItemsCannotBeListed(){var expected=item();seller.getInventory().setItemInMainHand(expected);seller.getInventory().setItemInMainHand(new ItemStack(Material.EMERALD));assertThrows(StateStore.Denied.class,()->plugin.list(seller,expected,3,5000));var fake=item();var meta=fake.getItemMeta();meta.getPersistentDataContainer().set(new NamespacedKey("tycoon","ui_icon"),PersistentDataType.STRING,"wallet");fake.setItemMeta(meta);seller.getInventory().setItemInMainHand(fake);assertThrows(StateStore.Denied.class,()->plugin.list(seller,fake,1,5000));assertTrue(store.listings(null).isEmpty());}
    @Test void saveFailureRestoresItemsAndRefundsAndUnlocksListing(){var row=listing();buyer.failOn=buyer.saves+1;plugin.buyItem(buyer,row.id(),5000,false);assertTrue(buyer.getInventory().isEmpty());assertEquals(100000,money.get(buyer.getUniqueId()));assertEquals("ACTIVE",store.listing(row.id()).state());assertFalse(db.unresolved(buyer.getUniqueId()));assertEquals(0,store.credit(seller.getUniqueId()));}
    @Test void finalSqlFaultKeepsEscrowLockedWithoutReplay(){var row=listing();db.execute("CREATE TRIGGER fail_sale BEFORE UPDATE ON civic_items WHEN NEW.state='SOLD' BEGIN SELECT RAISE(ABORT,'disk fault'); END");plugin.buyItem(buyer,row.id(),5000,false);assertEquals(3,buyer.getInventory().getItem(0).getAmount());assertEquals(99950,money.get(buyer.getUniqueId()));assertEquals("LOCKED",store.listing(row.id()).state());assertTrue(db.unresolved(buyer.getUniqueId()));assertFalse(plugin.engine.healthy());db.execute("DROP TRIGGER fail_sale");String id=store.listing(row.id()).receipt();plugin.admin(server.getConsoleSender(),new String[]{"완료",id,"확인"});assertEquals("SOLD",store.listing(row.id()).state());assertEquals(5000,store.credit(seller.getUniqueId()));assertEquals(3,buyer.getInventory().getItem(0).getAmount());assertEquals(99950,money.get(buyer.getUniqueId()));assertThrows(StateStore.Denied.class,()->db.resolveCivic(id,true,"op",()->{}));}
    @Test void reentrantWalletCannotCreateOrphanReservations(){var row=listing();int before=db.rows("SELECT id FROM receipts").size();walletHook=()->assertThrows(StateStore.Denied.class,()->plugin.found(seller,"중첩마을",seller.getWorld().getUID().toString(),0,0));plugin.buyItem(buyer,row.id(),5000,false);assertEquals(before+1,db.rows("SELECT id FROM receipts").size());assertNull(store.founded(seller.getUniqueId()));assertTrue(allowed(seller));}
    @Test void sellerOfflineGetsProceedsAndCollectsOnReturn(){var row=listing();seller.disconnect();plugin.buyItem(buyer,row.id(),5000,false);assertEquals(5000,store.credit(seller.getUniqueId()));assertEquals(100000,money.get(seller.getUniqueId()));}
    @Test void payoutConsumesOnlyReservedCreditLeavingLaterSales(){db.transaction(()->{store.creditInside(seller.getUniqueId().toString(),5000);return null;});var receipt=store.reserveCollection(seller.getUniqueId());db.review(receipt.id(),"uncertain");db.transaction(()->{store.creditInside(seller.getUniqueId().toString(),2000);return null;});db.resolveCivic(receipt.id(),true,"op",()->store.completeInside(receipt));assertEquals(2000,store.credit(seller.getUniqueId()));}
    @Test void guiCancelsBottomShiftNumberKeysAndDrag(){plugin.menus.market(seller,false,0);for(ClickType type:List.of(ClickType.SHIFT_LEFT,ClickType.NUMBER_KEY,ClickType.SWAP_OFFHAND,ClickType.DOUBLE_CLICK)){var e=new InventoryClickEvent(seller.getOpenInventory(),InventoryType.SlotType.CONTAINER,54,type,InventoryAction.MOVE_TO_OTHER_INVENTORY);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());}var drag=new InventoryDragEvent(seller.getOpenInventory(),new ItemStack(Material.STONE),new ItemStack(Material.STONE),false,Map.of(10,new ItemStack(Material.STONE)));server.getPluginManager().callEvent(drag);assertTrue(drag.isCancelled());server.getScheduler().performTicks(2);assertTrue(store.listings(null).isEmpty());}
    @Test void repeatedConfirmationOnlyBuysOnce(){var row=listing();plugin.menus.item(buyer,row.id(),row.price());var view=buyer.getOpenInventory();for(int i=0;i<3;i++){var e=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,30,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(e);}server.getScheduler().performTicks(2);assertEquals(99950,money.get(buyer.getUniqueId()));assertEquals(3,buyer.getInventory().getItem(0).getAmount());assertEquals(5000,store.credit(seller.getUniqueId()));}
    @Test void shiftFLinksActualMarketplaceAndTownMenus(){var menu=MockBukkit.loadWith(kr.minecraft.survival.menu.KoreanMenuPlugin.class,root.resolve("개발자료/플러그인/마을수첩/src/main/resources/plugin.yml").toFile());server.getPluginManager().addPermissions(menu.getDescription().getPermissions());seller.recalculatePermissions();seller.setSneaking(true);var event=new org.bukkit.event.player.PlayerSwapHandItemsEvent(seller,new ItemStack(Material.AIR),new ItemStack(Material.AIR));server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());server.getScheduler().performTicks(2);assertTrue(seller.getOpenInventory().getTopInventory().getItem(24).getItemMeta().getDisplayName().contains("개인상점"));click(seller,24);assertTrue(seller.getOpenInventory().getTitle().startsWith("개인상점"));menu.openFromNavigation(seller);server.getScheduler().performTicks(2);click(seller,16);assertTrue(seller.getOpenInventory().getTitle().startsWith("마을 |"));assertFalse(seller.isOp());}
    @Test void soldPlotCancelsOldOwnersAlreadyOpenChestClick(){var plot=town();var b=seller.getWorld().getBlockAt(0,65,0);b.setType(Material.CHEST);seller.openInventory(((org.bukkit.block.Chest)b.getState()).getInventory());plugin.sellPlot(seller,plot.id(),50000);plugin.buyPlot(buyer,plot.id(),50000);var e=new InventoryClickEvent(seller.getOpenInventory(),InventoryType.SlotType.CONTAINER,0,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());}
    @Test void disabledAddonLeavesNativeLandProtected(){town();server.getPluginManager().disablePlugin(plugin);assertFalse(allowed(buyer));var e=new BlockBreakEvent(buyer.getLocation().getBlock(),buyer);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());}
    kr.minecraft.survival.citytextures.CityTexturesPlugin textures(){var city=MockBukkit.loadWith(kr.minecraft.survival.citytextures.CityTexturesPlugin.class,root.resolve("개발자료/플러그인/도시화면/src/main/resources/plugin.yml").toFile());assertTrue(city.isEnabled());server.getPluginManager().addPermissions(city.getDescription().getPermissions());seller.recalculatePermissions();seller.performCommand("도시팩 메뉴켜기");return city;}
    @Test void texturesDecorateControlsButNeverReinterpretSaleItemNames(){var original=new ItemStack(Material.GOLD_INGOT,2);var meta=original.getItemMeta();meta.setDisplayName("내 돈 확인");meta.setItemModel(new NamespacedKey("custom","kept"));original.setItemMeta(meta);seller.getInventory().setItemInMainHand(original);plugin.list(seller,original,2,5000);plugin.menus.market(seller,false,0);textures();server.getScheduler().performTicks(2);var top=seller.getOpenInventory().getTopInventory();assertEquals(new NamespacedKey("tycoon","seller_crate"),top.getItem(46).getItemMeta().getItemModel());assertEquals(new NamespacedKey("custom","kept"),top.getItem(10).getItemMeta().getItemModel());click(seller,10);assertEquals(new NamespacedKey("custom","kept"),seller.getOpenInventory().getTopInventory().getItem(22).getItemMeta().getItemModel());assertEquals(new NamespacedKey("tycoon","confirm"),seller.getOpenInventory().getTopInventory().getItem(30).getItemMeta().getItemModel());}
    Map<String,Object> snapshot(){var view=seller.getOpenInventory();List<Object> slots=new ArrayList<>();for(var item:view.getTopInventory().getContents()){if(item==null){slots.add(null);continue;}var meta=item.getItemMeta();Map<String,Object> entry=new LinkedHashMap<>();entry.put("name",meta.hasDisplayName()?meta.getDisplayName():item.getType().name());entry.put("lore",meta.hasLore()?meta.getLore():List.of());entry.put("amount",item.getAmount());entry.put("material",item.getType().name());entry.put("model",meta.hasItemModel()?meta.getItemModel().toString():null);entry.put("glow",false);slots.add(entry);}return Map.of("title",view.getTitle(),"slots",slots);}
    @Test void exportRealInventorySnapshotsForKoreanPreview()throws Exception{town();var plot=store.plots().getFirst();plugin.sellPlot(seller,plot.id(),50000);listing();textures();Map<String,Object> screens=new LinkedHashMap<>();plugin.menus.town(seller);server.getScheduler().performTicks(2);screens.put("town",snapshot());plugin.menus.plots(seller,"판매",0);server.getScheduler().performTicks(2);screens.put("plots",snapshot());plugin.menus.plotEditor(seller,plot.id(),50000);server.getScheduler().performTicks(2);screens.put("plot_editor",snapshot());plugin.menus.market(seller,false,0);server.getScheduler().performTicks(2);screens.put("market",snapshot());plugin.menus.listEditor(seller,item(),3,5000);server.getScheduler().performTicks(2);screens.put("listing",snapshot());plugin.menus.item(seller,store.listings(null).getFirst().id(),5000);server.getScheduler().performTicks(2);screens.put("confirmation",snapshot());Path out=root.resolve("개발자료/플러그인/마을상점/build/menu-snapshots.json");Files.createDirectories(out.getParent());Files.writeString(out,new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(screens));}

}
